/// The composite delivery gateway (#60), resolved through the GENERATED `delivery` service
/// binding -- the SAME construction the monolith composition root performs: `independent` is the
/// rider pool (deliberate no-op), partner channels join when their credentials are configured,
/// and an unwired channel falls through via offer timeout.
fn delivery_partner_binding() -> std::sync::Arc<dyn application::generated::services::DeliveryService> {
    infrastructure::generated::service_bindings::delivery_service(|| {
        let mut gateway = infrastructure::CompositeDeliveryGateway::new().with_channel(
            "independent",
            std::sync::Arc::new(application::ports::NoopDeliveryService),
        );
        if let Some(avelo) = avelo37_adapter::Avelo37DeliveryGateway::from_env() {
            gateway = gateway.with_channel("avelo37", std::sync::Arc::new(avelo));
        }
        let coopcycle_registry = coopcycle_adapter::CoopCycleRegistry::from_env()
            .unwrap_or_else(|e| {
                tracing::warn!(error = %e, key = "COOPCYCLE_INSTANCES", "misconfigured, treating as unset");
                None
            })
            .unwrap_or_default();
        if !coopcycle_registry.is_empty() {
            gateway = gateway.with_channel(
                "coopcycle",
                std::sync::Arc::new(coopcycle_adapter::CoopCycleDeliveryGateway::new(coopcycle_registry)),
            );
        }
        if let Some(config) = uber_direct_adapter::UberDirectConfig::from_env().unwrap_or_else(|e| {
            tracing::warn!(error = %e, key = "UBER_DIRECT_*", "misconfigured, treating as unset");
            None
        }) {
            gateway = gateway.with_channel(
                "uber_direct",
                std::sync::Arc::new(uber_direct_adapter::UberDirectDeliveryGateway::new(config)),
            );
        }
        tracing::info!(
            binding = "delivery",
            impl_ = "composite",
            wired_channels = ?gateway.wired_channels(),
            "delivery gateway wired (unwired channels fall through via offer timeout)"
        );
        std::sync::Arc::new(gateway)
    })
    .expect("delivery service binding (services.yaml)")
}
